import java.util.Arrays;
import java.util.Scanner;

public class LuckyTickets {
    private static final int MOD = 998244353;
    private static final int ROOT = 15311432;
    private static final int INVROOT = 469870224;

    private static int reverseBits(int n, int k) {
        return Integer.reverse(n) >>> (32 - k);
    }

    private static long modularInverse(int a) {
        return modularExponentiation(a, MOD - 2);
    }

    private static long modularExponentiation(int a, int p) {
        if (p == 0) {
            return 1;
        }
        long halfPower = modularExponentiation(a, p / 2);
        long result = (halfPower * halfPower) % MOD;
        if (p % 2 == 1) {
            result = (result * a) % MOD;
        }
        return result;
    }

    private static void performNTT(long[] coefficients, int logSize, boolean inverseTransform) {
        int baseRoot = inverseTransform ? INVROOT : ROOT;
        long root = modularExponentiation(baseRoot, (int) Math.pow(2, 23 - logSize));
        long[] roots = new long[logSize];
        roots[logSize - 1] = root;
        for (int i = logSize - 1; i > 0; i--) {
            roots[i - 1] = (roots[i] * roots[i]) % MOD;
        }
        for (int s = 0; s < logSize; s++) {
            int segmentLength = 1 << s;
            for (int start = 0; start < coefficients.length; start += 2 * segmentLength) {
                long currentRoot = 1;
                for (int j = start; j < start + segmentLength; j++) {
                    long temp = (currentRoot * coefficients[j + segmentLength]) % MOD;
                    long u = coefficients[j];
                    coefficients[j] = (u + temp) % MOD;
                    coefficients[j + segmentLength] = (u - temp) % MOD;
                    currentRoot = (roots[s] * currentRoot) % MOD;
                }
            }
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt() / 2;
        int m = scanner.nextInt();
        int[] numbers = new int[m];
        for (int i = 0; i < m; i++) {
            numbers[i] = scanner.nextInt();
        }
        Arrays.sort(numbers);
        int minSize = n * numbers[m - 1] + 2;
        int logSize = 0;
        int size = 1;
        while (size < minSize) {
            size <<= 1;
            logSize++;
        }
        long[] array = new long[size];
        for (int num : numbers) {
            array[reverseBits(num, logSize)] = 1;
        }
        performNTT(array, logSize, false);
        for (int i = 0; i < size; i++) {
            array[i] = modularExponentiation((int) array[i], n);
        }
        long[] tempArray = new long[size];
        for (int i = 0; i < size; i++) {
            tempArray[reverseBits(i, logSize)] = array[i] % MOD;
        }
        array = tempArray;
        performNTT(array, logSize, true);
        long total = 0;
        for (int i = 0; i < size; i++) {
            total = (total + array[i] * array[i]) % MOD;
        }
        long invSize = modularInverse(size);
        System.out.println((((total * invSize) % MOD) * invSize) % MOD);
    }
}
